const InstanceField = preload("res://instancing/instance_field.gd")

func run():
    var field = InstanceField.new()
    var mesh = field.build()
    ResourceSaver.save(mesh, "res://build/field.res")

    var query_min = Vector3(-1.0, 0.0, -3.0)
    var query_max = Vector3(5.0, 1.5, 0.0)
    var result = field.cull(query_min, query_max)

    var report = {
        "instance_count": mesh.instance_count,
        "transform_format": mesh.transform_format,
        "use_colors": mesh.use_colors,
        "use_custom_data": mesh.use_custom_data,
        "query_min": [query_min.x, query_min.y, query_min.z],
        "query_max": [query_max.x, query_max.y, query_max.z],
        "visible_indices": result.indices,
        "visible_count": result.count,
        "weight_sum": result.weight_sum,
        "flagged_count": result.flagged_count
    }

    var file = FileAccess.open("res://build/report.json", FileAccess.WRITE)
    file.store_string(JSON.stringify(report, "", false))
    file.close()
    print("Done")

